-- Continuación: servicios 4, 5 y 6

INSERT INTO public.servicios (slug, title, short_title, seo_title, description, excerpt, cover_url, cover_alt, icon, "order", price_from, price_unit, duration, features, includes, faqs, body_md, draft, updated_at) VALUES

('reforma-de-locales-comerciales',
 'Reforma de locales comerciales y oficinas',
 'Locales y oficinas',
 'Reforma de locales comerciales en Sabadell',
 'Reforma de locales, oficinas y clínicas en Sabadell con proyecto técnico, licencia de actividad y obra nocturna para no cerrar tu negocio. Plazos firmados.',
 'Adecuación de locales y oficinas con proyecto técnico, licencia de actividad y ejecución por fases o en horario nocturno para minimizar el cierre.',
 'https://donirysodidyakcmsfhc.supabase.co/storage/v1/object/public/imagenes/servicios/reforma-de-locales-comerciales.webp',
 'Local comercial reformado con iluminación técnica y mobiliario de diseño',
 'ruler', 4, 380, 'm²', '4-10 semanas',
 '["Proyecto técnico y licencia de actividad incluidos","Cumplimiento de accesibilidad y protección contra incendios","Trabajo por fases o nocturno para no cerrar el negocio","Instalaciones de climatización y datos dimensionadas","Certificados finales para inspección municipal"]',
 '["Estudio de viabilidad y proyecto de adecuación","Tramitación de licencia y declaración responsable","Distribución con tabiquería seca y aislamiento acústico","Electricidad, iluminación técnica, datos y climatización","Rotulación, escaparate y accesos accesibles"]',
 '[{"question":"¿Necesito licencia para reformar mi local?","answer":"Sí. La adecuación de un local para actividad requiere declaración responsable o licencia según el uso y la superficie, con proyecto firmado por técnico. Preparamos la documentación y la presentamos en el ayuntamiento por ti."},{"question":"¿Podéis trabajar sin cerrar el negocio?","answer":"Sí. Organizamos la obra por fases sectorizadas con paneles antipolvo o concentramos los trabajos ruidosos en horario nocturno y fines de semana. Encarece la obra entre un 10 % y un 20 %, pero evita la pérdida de facturación."},{"question":"¿Qué normativa de accesibilidad debo cumplir?","answer":"Los locales de pública concurrencia necesitan itinerario accesible, puerta de paso libre mínima de 80 cm y aseo adaptado cuando hay más de un aseo. En obra nueva o cambio de uso se aplica el DB-SUA del CTE de forma íntegra."},{"question":"¿Cuánto tarda la reforma de una oficina?","answer":"Una oficina de 150-250 m² con tabiquería, climatización, iluminación y datos se ejecuta en 6-10 semanas. Los plazos de licencia son paralelos a la obra cuando la tramitación es por declaración responsable."}]',
 E'## Cada día cerrado es facturación perdida\n\nEn un local en funcionamiento el plazo pesa tanto como el precio. Planificamos la obra con hitos diarios, sectorizamos las zonas con paneles antipolvo y concentramos las tareas ruidosas fuera del horario comercial para que sigas abierto el máximo tiempo posible.\n\n## Proyecto, licencia y responsabilidad técnica\n\nTrabajamos con arquitecto e ingeniero para el proyecto de adecuación, el cumplimiento del CTE en protección contra incendios (DB-SI), accesibilidad (DB-SUA) y aislamiento acústico (DB-HR). Presentamos la documentación en el ayuntamiento y respondemos ante la inspección con los certificados de instalación y el fin de obra.\n\n## Instalaciones dimensionadas para uso intensivo\n\nUn local no es una vivienda: la carga eléctrica, la renovación de aire y la climatización se calculan según ocupación y actividad. Instalamos cuadros con protección selectiva, iluminación LED con temperatura de color adecuada al producto, cableado estructurado categoría 6A y equipos de climatización inverter con control por zonas.\n\n## Sectores con los que trabajamos habitualmente\n\nRetail y showrooms, hostelería, clínicas dentales y médicas, centros de fisioterapia, oficinas y coworkings. Cada actividad tiene requisitos propios de higiene, insonorización o extracción que resolvemos en fase de proyecto, no durante la obra.',
 false, '2025-11-18'::timestamptz),

('rehabilitacion-de-fachadas',
 'Rehabilitación de fachadas y eficiencia energética',
 'Fachadas y SATE',
 'Rehabilitación de fachadas en Sabadell',
 'Rehabilitación de fachadas con SATE, ITE y subvenciones Next Generation en Sabadell. Ahorra hasta el 40 % en climatización con aislamiento certificado.',
 'Aislamiento térmico por el exterior (SATE), reparación de cornisas e ITE para comunidades de propietarios, con gestión de ayudas y certificado energético.',
 'https://donirysodidyakcmsfhc.supabase.co/storage/v1/object/public/imagenes/servicios/rehabilitacion-de-fachadas.webp',
 'Andamio instalado en la rehabilitación de una fachada de edificio',
 'roller', 5, 95, 'm²', '6-14 semanas',
 '["SATE con espesores calculados por certificado energético","Gestión de subvenciones y deducciones fiscales","Reparación de cornisas, balcones y humedades","Informe ITE y coordinación con administrador de fincas","Andamio homologado con plan de seguridad"]',
 '["Inspección técnica y catas del estado del cerramiento","Proyecto y estudio de mejora energética","Montaje de andamio y protecciones colectivas","Sistema SATE, mortero de regularización y acabado elástico","Certificado energético final y libro del edificio"]',
 '[{"question":"¿Cuánto se ahorra con un SATE?","answer":"Un aislamiento exterior bien ejecutado reduce entre el 30 % y el 40 % la demanda de calefacción y refrigeración, elimina puentes térmicos y evita condensaciones interiores. El retorno de la inversión ronda los 8-12 años con las ayudas vigentes."},{"question":"¿Hay subvenciones para rehabilitar la fachada?","answer":"Sí. Los programas de rehabilitación energética financian entre el 40 % y el 80 % del coste según la mejora de consumo conseguida, además de deducciones en el IRPF. Preparamos la documentación técnica que exige la convocatoria."},{"question":"¿Qué es la ITE y cada cuánto se pasa?","answer":"La Inspección Técnica de Edificios es obligatoria en Sabadell para edificios de más de 30 años y se renueva cada 10. Si el informe resulta desfavorable, hay plazo para ejecutar las obras de subsanación que redactamos y valoramos."},{"question":"¿Cuánto dura la obra de una fachada?","answer":"Entre 6 y 14 semanas según superficie, número de balcones y meteorología. El andamio permanece montado todo el periodo, por lo que reforzamos la seguridad de los accesos y avisamos a los vecinos de cada fase."}]',
 E'## Rehabilitar la envolvente es la inversión más rentable\n\nEn edificios anteriores a 1980 la fachada suele carecer de aislamiento. Actuar sobre la envolvente reduce de forma inmediata la factura energética de todos los vecinos, elimina humedades por condensación y revaloriza los pisos del inmueble.\n\n## SATE: aislamiento por el exterior\n\nEl sistema SATE adhiere paneles aislantes (EPS grafitado, lana de roca o XPS en zócalos) sobre el soporte existente, con malla de refuerzo, mortero y acabado elástico transpirable. Se ejecuta sin reducir la superficie útil de las viviendas y sin obras en el interior de las casas.\n\n## Patologías que resolvemos\n\nDesprendimientos de plaqueta y mortero, armaduras oxidadas en cantos de forjado, grietas por dilatación, filtraciones en balcones, cornisas degradadas y remates de albardilla mal resueltos. Cada patología se documenta con catas antes de presupuestar para que no aparezcan sorpresas con el andamio montado.\n\n## Trabajo con comunidades de propietarios\n\nPresentamos el proyecto en junta con memoria, mediciones y calendario, ofrecemos alternativas por niveles de inversión y coordinamos con el administrador de fincas la comunicación a los vecinos durante toda la obra.',
 false, '2025-11-18'::timestamptz),

('instalaciones-y-climatizacion',
 'Instalaciones, climatización y aerotermia',
 'Instalaciones',
 'Instalaciones y climatización en Sabadell',
 'Renovación de electricidad, fontanería, aerotermia y aire acondicionado por conductos en Sabadell. Boletines y certificados oficiales incluidos.',
 'Electricidad certificada, fontanería nueva, aerotermia y climatización por conductos con cálculo de cargas, boletín oficial y puesta en marcha.',
 'https://donirysodidyakcmsfhc.supabase.co/storage/v1/object/public/imagenes/servicios/instalaciones-y-climatizacion.webp',
 'Instalación de conductos de climatización en el falso techo de una vivienda',
 'lightning', 6, 2400, 'instalación', '1-3 semanas',
 '["Boletín eléctrico y certificados de instalación oficiales","Cálculo de cargas térmicas antes de dimensionar equipos","Aerotermia y bombas de calor de alta eficiencia","Conductos con difusión por estancias y control por zonas","Domótica básica sin dependencia de la nube"]',
 '["Sustitución de cuadro eléctrico y protecciones","Circuitos independientes y tomas según CTE y REBT","Fontanería en multicapa con llaves de corte por zona","Climatización por conductos o split con desagüe garantizado","Puesta en marcha, equilibrado y documentación final"]',
 '[{"question":"¿Cuándo hay que cambiar la instalación eléctrica?","answer":"Si el cuadro tiene fusibles, no hay diferencial, el cableado es de menos de 1,5 mm² o supera los 35 años, la instalación está fuera de norma. Renovarla es imprescindible antes de instalar cocina eléctrica o aerotermia."},{"question":"¿Merece la pena la aerotermia en un piso?","answer":"Sí cuando hay espacio para la unidad exterior y radiadores de baja temperatura o suelo radiante. Rinde 3-4 kWh térmicos por kWh eléctrico consumido y da calefacción, refrigeración y agua caliente con un único equipo."},{"question":"¿Aire por conductos o splits?","answer":"Los conductos ofrecen mejor reparto y menos ruido, pero necesitan falso techo de unos 30 cm en pasillos. Los splits son más económicos y viables cuando no hay altura libre suficiente para el paso de conductos."},{"question":"¿Entregáis boletín eléctrico?","answer":"Sí. Somos instaladores autorizados y emitimos el certificado de instalación eléctrica sellado por industria, imprescindible para altas de suministro, aumentos de potencia y para la venta o alquiler de la vivienda."}]',
 E'## Las instalaciones son la mitad de una buena reforma\n\nLos acabados se ven, pero lo que determina el confort y la seguridad de la vivienda son los circuitos, las tuberías y los equipos. Dimensionamos cada instalación con cálculo, no por costumbre, y entregamos toda la documentación oficial al terminar.\n\n## Electricidad conforme al REBT\n\nSustituimos cuadros obsoletos por cuadros con diferenciales e interruptores magnetotérmicos por circuito, revisamos la toma de tierra con medición de resistencia y distribuimos los circuitos según el grado de electrificación real de la vivienda. Emitimos boletín para altas y aumentos de potencia.\n\n## Climatización dimensionada por cálculo\n\nAntes de elegir equipos calculamos las cargas térmicas de cada estancia según orientación, superficie acristalada y aislamiento. Un equipo sobredimensionado cicla en exceso, consume más y crea corrientes molestas; uno insuficiente no alcanza consigna en los picos de julio.\n\n## Agua caliente y eficiencia\n\nAerotermia, bomba de calor para ACS o caldera de condensación según necesidades y espacio disponible. Aislamos los tramos de tubería de agua caliente para reducir pérdidas y colocamos recirculación en viviendas grandes para evitar el desperdicio de agua mientras se calienta.',
 false, '2025-11-18'::timestamptz);
